fn iabs(v: i32) -> i32 {
    if v < 0 { -v } else { v }
}

fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 60 * 8);
        host::display::state_set(2, 60 * 8);
    }
    let idx: i32 = (t / 6) & 31;
    let rx: i32 = cx + tab[idx] * 140 / 127;
    let ry: i32 = cy + tab[(idx + 8) & 31] * 140 / 127;
    let mut fx: i32 = host::display::state_get(1);
    let mut fy: i32 = host::display::state_get(2);
    let dx: i32 = rx * 8 - fx;
    let dy: i32 = ry * 8 - fy;
    let len: i32 = (iabs(dx) + iabs(dy)) / 8 + 1;
    fx = fx + dx * 5 / len;
    fy = fy + dy * 5 / len;
    let mut caught: i32 = host::display::state_get(3);
    let ex: i32 = rx - fx / 8;
    let ey: i32 = ry - fy / 8;
    if ex * ex + ey * ey < 400 {
        caught = caught + 1;
        fx = 60 * 8;
        fy = 60 * 8;
    }
    host::display::state_set(1, fx);
    host::display::state_set(2, fy);
    host::display::state_set(3, caught);
    host::display::clear(0x0e0e12);
    let mut i: i32 = 0;
    while i < 16 {
        let a: i32 = i * 2;
        host::display::fill_rect(cx + tab[a] * 140 / 127 - 1, cy + tab[(a + 8) & 31] * 140 / 127 - 1, 2, 2, 0x303840);
        i = i + 1;
    }
    host::display::draw_line(fx / 8, fy / 8, rx, ry, 0x303030);
    host::display::fill_rect(rx - 5, ry - 5, 10, 10, 0xf0f0f0);
    host::display::fill_rect(fx / 8 - 6, fy / 8 - 6, 12, 12, 0xe06020);
    host::display::draw_string(8, 8, "CAUGHT", 0x808080, 1);
    host::display::draw_number(70, 8, caught, 0xffffff, 1);
    host::display::present();
}
